def calculate(s: str) -> int:
    # Initialize variables
    num = 0
    ope = '+'  # Default operator
    stack = []

    # Process each character in the string
    for i in s:
        # Check if character is numeric
        if i.isnumeric():
            num = num * 10 + int(i)

        # Check if character is an operator or end of string
        if i in '+-*/' or i == ' ':
            # Handle the current number based on the operator
            if ope == '+':
                stack.append(num)
            elif ope == '-':
                stack.append(-num)
            elif ope == '*':
                stack.append(stack.pop() * num)
            elif ope == '/':
                # Integer division truncating toward zero
                stack.append(int(stack.pop() / num))

            # Update operator and reset number
            ope = i
            num = 0

    # Sum all elements in stack
    return sum(stack)

