        top12 = (top12 * i) % 100000000000  # Last 12 digits
        # Update tail5 (last 5 digits)
        tail5 = (tail5 * i) % 100000

    zero = min(c2, c5)

    # Convert top12 to string
    top12_str = str(top12)

    if len(top12_str) <= 10:
        return top12_str + 'e' + str(zero)
    else:
        return top12_str[:5] + '...' + str(tail5) + 'e' + str(zero)
